import{c as t,Q as a,j as o,m as r}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Categories","description":"","frontmatter":{},"headers":[],"relativePath":"guide/categories.md","filePath":"guide/categories.md","lastUpdated":null}'),n={name:"guide/categories.md"};function i(s,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h1><p>Categories are the taxonomy the ledger speaks in. Everything — Today, Budget envelopes, Reports, and the Copilot — aggregates by category.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><ul><li><strong>Category</strong> — name, color swatch, and group. Groups are user-defined (e.g. “Living”, “Growth”).</li><li><strong>Spending type</strong> — <code>Need</code> · <code>Want</code> · <code>Saving</code> · <code>Investment</code> (Sethi). Powers the allocation donut on Budget and the wellness context. Set it per category; the Copilot treats miscoded types as a fixable problem.</li><li><strong>Guidance</strong> — optional per-category hint rendered in the picker (e.g. “Groceries · Need · 12% of income last month”).</li></ul><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><p><strong>Categories → Month / Prior period / YTD.</strong> Each scope shows spent, budgeted, and count. Change the scope to catch drift: a category that looks calm this month may be 40% over YTD.</p><h2 id="guidance-spending-type" tabindex="-1">Guidance &amp; spending type <a class="header-anchor" href="#guidance-spending-type" aria-label="Permalink to &quot;Guidance &amp; spending type&quot;">​</a></h2><p>The category drawer shows the spending type and the last few months of spend so you can judge a type change. Moving “Dining” from Want to Need shifts the allocation and changes the Copilot’s nudges — it will warn differently.</p><h2 id="palettes" tabindex="-1">Palettes <a class="header-anchor" href="#palettes" aria-label="Permalink to &quot;Palettes&quot;">​</a></h2><p>Swatches come from <code>palette.rs</code>. The category stream bar and donor bars reuse those swatches so a color means the same thing in Today, Budget, and Reports.</p><h2 id="when-to-edit-vs-create" tabindex="-1">When to edit vs create <a class="header-anchor" href="#when-to-edit-vs-create" aria-label="Permalink to &quot;When to edit vs create&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Do</th></tr></thead><tbody><tr><td>Groceries vs Dining blur together</td><td>Keep two categories; fix with rules</td></tr><tr><td>One-off tax payment</td><td>Create a “Taxes” category, or use an existing “Government” if you have one</td></tr><tr><td>Category feels like two things</td><td>Split the transaction instead of inventing a hybrid category</td></tr></tbody></table><p>See also: <a href="/FinSight/guide/transactions">Transactions</a>, <a href="/FinSight/automation/rules">Rules</a>.</p>',13)])])}const u=t(n,[["render",i]]);export{p as __pageData,u as default};
